import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"蜥族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/蜥族.md","filePath":"表层/种族/蜥族.md","lastUpdated":null}'),l={name:"表层/种族/蜥族.md"};function i(n,a,h,s,d,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="蜥族" tabindex="-1">蜥族 <a class="header-anchor" href="#蜥族" aria-label="Permalink to &quot;蜥族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>蜥族（也称蜥蜴族）是黑暗时代后期出现的新型种族，属于<strong>非毛系种族</strong>，身体有鳞片。蜥族自称**&quot;亚龙族&quot;**而非蜥族，宣称身负龙族血脉。族群规模小，不参与种族争霸。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>体表</strong>：非毛系，身体覆盖鳞片。</li><li><strong>形态</strong>：直立行走的蜥蜴类福瑞形态。</li></ul><blockquote><p>待定：体型与狼族、鹿族相似——暂无明确依据。</p></blockquote><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><ul><li><strong>非毛系</strong>：与绝大多数毛茸茸的福瑞种族不同，蜥族以鳞片为特征，属于少数非毛系智慧族群之一。</li><li><strong>亚龙宣称</strong>：蜥族始终宣称本族身负龙族血脉，为亚龙族而非蜥族。</li><li><strong>不参与争霸</strong>：蜥族执迷于追寻龙族的身影，不介入大陆各族之间的权力斗争。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><p>蜥族为黑暗时代后期的新型种族，初期主要受兔族庇护，后逐渐走向独立。因坚信身负龙族血脉，蜥族举族踏上寻龙之路。</p><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>蜥族族群规模小，虽然未在任何重大政治格局中扮演角色，但在漫长的寻龙历程中，通过点滴的蛛丝马迹，逐渐将其居住地迁徙至靠近龙族隐居地的地带附近。据说有人在那附近见过龙的身影，蜥族因此成为与龙接触传闻最多的种族。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./龙族">龙族</a></li><li><a href="./兔族">兔族</a></li></ul><hr>',19)])])}const p=e(l,[["render",i]]);export{_ as __pageData,p as default};
